import { Injectable, inject } from '@angular/core';

import { Title } from '@angular/platform-browser';
import { ActivatedRouteSnapshot } from '@angular/router';
import { LangChangeEvent, TranslateService } from '@ngx-translate/core';
import { Observable } from 'rxjs';
import { AuthService } from './auth.service';
import { GlobalEventService } from './global-event.service';
import { WINDOW_LOCATION } from './injection-tokens';
import { StartupService } from './startup.service';

const APPLICATION_TRANSLATE_PATH = 'APPLICATION';

@Injectable({
  providedIn: 'root',
})
export class AppGuard {
  private authService = inject(AuthService);
  private startupService = inject(StartupService);
  private titleService = inject(Title);
  private globalEventService = inject(GlobalEventService);
  private location = inject(WINDOW_LOCATION);
  private translateService = inject(TranslateService);

  canActivate(next: ActivatedRouteSnapshot): Observable<boolean> | Promise<boolean> | boolean {
    if (!next.data.hasOwnProperty('appId')) {
      console.error('AppGuard Error: Missing "appId" property in route declaration. Please add the property to the route\'s data');
      return false;
    }
    const appId = next.data.appId;
    const foundAppProfile = this.authService.user.profileGroup.profiles.find((profile) => profile.applicationName === appId);
    if (!foundAppProfile) {
      this.location.href = this.startupService.getPortalUrl();
      return false;
    }

    this.startupService.CURRENT_APP_ID = appId;
    if (this.translateService.currentLang) {
      this.titleService.setTitle(this.translateService.instant(`${APPLICATION_TRANSLATE_PATH}.${appId}.NAME`));
    }
    this.translateService.onLangChange.subscribe((_: LangChangeEvent) => {
      this.titleService.setTitle(this.translateService.instant(APPLICATION_TRANSLATE_PATH + '.' + appId + '.NAME'));
    });

    // set user default tenant Identifier whenever we switch pages
    this.startupService.setTenantIdentifier();
    // emit page change event
    this.globalEventService.pageEvent.next(appId);

    return true;
  }
}
