import { HttpHeaders, HttpParams, HttpResponse } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable, Subject, switchMap } from 'rxjs';
import { map, shareReplay, tap } from 'rxjs/operators';
import { AccessContractApiService } from '../api/access-contract-api.service';
import { AccessContract } from '../../../lib/models/access-contract.interface';
import { SearchService } from '../vitamui-table';
import { SnackBarService } from '../components/snack-bar/snack-bar.service';
import { ExternalParametersService } from '../externalParameters.service';
import { ExternalParameters } from '../externalParameters.enum';
import { VitamuiHttpHeaders } from '../vitamui-http-headers.enum';

@Injectable({
  providedIn: 'root',
})
export class AccessContractService extends SearchService<AccessContract> {
  private accessContractApi: AccessContractApiService;
  private snackBarService = inject(SnackBarService);
  private externalParameterService = inject(ExternalParametersService);

  /** Observable of current access contract ID */
  currentAccessContractId$: Observable<string> = this.externalParameterService.getUserExternalParameters().pipe(
    map((parameters) => parameters.get(ExternalParameters.PARAM_ACCESS_CONTRACT)),
    shareReplay(1), //cached
  );
  /** Observable of current access contract */
  currentAccessContract$: Observable<AccessContract> = this.currentAccessContractId$.pipe(
    switchMap((accessContractId) => this.get(accessContractId)),
    shareReplay(1), //cached
  );

  updated = new Subject<AccessContract>();

  constructor() {
    const accessContractApi = inject(AccessContractApiService);

    super(accessContractApi, 'ALL');

    this.accessContractApi = accessContractApi;
  }

  get(id: string): Observable<AccessContract> {
    const headers = new HttpHeaders().append('Content-Type', 'application/json');
    return this.accessContractApi.getOne(encodeURI(id), headers);
  }

  getAll(): Observable<AccessContract[]> {
    const params = new HttpParams().set('embedded', 'ALL');
    return this.accessContractApi.getAllByParams(params);
  }

  getAllForTenant(tenantId: string): Observable<AccessContract[]> {
    // TODO: Cgeck add of tenantId
    const params = new HttpParams().set('embedded', 'ALL');
    const headers = new HttpHeaders().set(VitamuiHttpHeaders.X_TENANT_ID, tenantId);
    return this.accessContractApi.getAllByParams(params, headers);
  }

  exists(name: string): Observable<boolean> {
    const accessContract = { name, identifier: name } as AccessContract;
    return this.accessContractApi.check(accessContract, this.headers);
  }

  existsProperties(properties: { name?: string; identifier?: string }): Observable<any> {
    const existContract: any = {};
    if (properties.name) {
      existContract.name = properties.name;
    }
    if (properties.identifier) {
      existContract.identifier = properties.identifier;
    }

    const context = existContract as AccessContract;
    return this.accessContractApi.check(context, this.headers);
  }

  patch(data: { id: string; [key: string]: any }): Observable<AccessContract> {
    return this.accessContractApi.patch(data).pipe(
      tap((response) => this.updated.next(response)),
      tap({
        next: (response) => {
          this.snackBarService.open({
            message: 'SNACKBAR.ACCESS_CONTRACT_UPDATED',
            translateParams: {
              name: response.name,
            },
            icon: 'vitamui-icon-contrat',
          });
        },
        error: (error) => {
          this.snackBarService.open({ message: error.error.message, translate: false });
        },
      }),
    );
  }

  create(accessContract: AccessContract): Observable<AccessContract> {
    return this.accessContractApi.create(accessContract).pipe(
      tap(
        (response: AccessContract) => {
          this.snackBarService.open({
            message: 'SNACKBAR.ACCESS_CONTRACT_CREATED',
            translateParams: {
              name: response.name,
            },
            icon: 'vitamui-icon-contrat',
          });
        },
        (error) => {
          this.snackBarService.open({ message: error.error.message, translate: false });
        },
      ),
    );
  }

  setTenantId(tenantIdentifier: number) {
    this.headers = new HttpHeaders().set(VitamuiHttpHeaders.X_TENANT_ID, tenantIdentifier.toString());
  }

  public downloadImportAccessContractFileModel(): Observable<HttpResponse<Blob>> {
    return this.accessContractApi.getImportAccessContractFileModel();
  }

  public exportAccessContracts(): Observable<HttpResponse<Blob>> {
    return this.accessContractApi.exportAccessContracts();
  }
}
