import { HttpClient } from '@angular/common/http';
import { Injectable, inject } from '@angular/core';
import { Observable } from 'rxjs';
import { map } from 'rxjs/operators';
import { Ontology } from '../../../lib/models/ontology';
import { BaseHttpClient } from '../base-http-client';
import { BASE_URL } from '../injection-tokens';
import { Collection, Schema } from '../models';

@Injectable({
  providedIn: 'root',
})
export class SchemaApiService extends BaseHttpClient<Ontology> {
  constructor() {
    const http = inject(HttpClient);
    const baseUrl = inject(BASE_URL);

    super(http, `${baseUrl}/schemas`);
  }

  public getSchemas(collections: Collection[]): Observable<Schema[]> {
    return this.http.get<Schema[]>(this.apiUrl, { params: { collections } });
  }

  public getSchema(collection: Collection): Observable<Schema> {
    return this.getSchemas([collection]).pipe(map((schemas) => schemas[0]));
  }

  public getArchiveUnitProfileSchema(archiveUnitProfileId: string): Observable<Schema> {
    return this.http.get<Schema>(`${this.apiUrl}/archive-unit-profile/${archiveUnitProfileId}`);
  }

  public deleteSchema(paths: string[]): Observable<string> {
    return this.http.delete(this.apiUrl, { body: paths, responseType: 'text' });
  }
}
